library(testthat)

lc_val_strip <- function(x) {
  if (is.null(x)) return("")
  s <- paste(as.character(x), collapse = " ")
  s <- gsub("</?[a-zA-Z][^>]*>", " ", s)
  trimws(gsub("[[:space:]]+", " ", s))
}

lc_val_sum <- function(res, stat) {
  df <- res$summary$asDF
  m <- df[df$statistic == stat, , drop = FALSE]
  stopifnot(nrow(m) == 1L)
  m$value[1]
}

lc_val_cor <- function(res, pattern, fixed = TRUE) {
  df <- res$correlation$asDF
  idx <- if (fixed) which(df$measure == pattern) else grep(pattern, df$measure)
  stopifnot(length(idx) == 1L)
  df[idx, , drop = FALSE]
}

lc_val_make_r <- function(n, target_r) {
  x <- seq_len(n)
  xc <- x - mean(x)
  z <- xc^2 - mean(xc^2)
  z <- z - (sum(z * xc) / sum(xc^2)) * xc
  z <- z / sqrt(sum(z^2))
  xu <- xc / sqrt(sum(xc^2))
  data.frame(x = x, y = 50 + 10 * (target_r * xu + sqrt(1 - target_r^2) * z))
}

