test_that("C01-C08: summary table matches closed-form hand arithmetic with tie and NA", {
  # Oracle: exact hand derivation on n = 8 complete rows (+ 1 NA excluded)
  skip_if_not_installed("jmvcore")
  skip_if_not_installed("ggplot2")

  d <- data.frame(
    time = c(1, 2, 2, 4, 5, 6, 8, 10, NA),
    val  = c(2, 5, 3, 8, 10, 12, 15, 21, 99)
  )
  res <- suppressWarnings(ClinicoPath::linechart(
    data = d, xvar = "time", yvar = "val", groupby = NULL, trendline = TRUE
  ))

  expect_equal(as.numeric(lc_val_sum(res, "Number of Observations")), 8)
  expect_equal(as.numeric(lc_val_sum(res, "Number of X-axis Points")), 7)
  expect_equal(as.numeric(lc_val_sum(res, "Number of Groups")), 1)
  expect_equal(lc_val_sum(res, "Y Mean"), "9.50")
  expect_equal(lc_val_sum(res, "Y Median"), "9.00")
  expect_equal(lc_val_sum(res, "Y Standard Deviation"), "6.44")
  expect_equal(lc_val_sum(res, "Y Range"), "2.00 - 21.0")
})

test_that("C09-C13: Pearson r, Fisher-z 95% CI, p-value, R-squared, and OLS slope match closed-form oracle", {
  # Oracle: exact hand sums Sxx=69.5, Syy=290, Sxy=141 on n=8 complete rows; Fisher-z CI & Student-t p
  skip_if_not_installed("jmvcore")
  skip_if_not_installed("ggplot2")

  d <- data.frame(
    time = c(1, 2, 2, 4, 5, 6, 8, 10, NA),
    val  = c(2, 5, 3, 8, 10, 12, 15, 21, 99)
  )
  res <- suppressWarnings(ClinicoPath::linechart(
    data = d, xvar = "time", yvar = "val", trendline = TRUE
  ))

  r_exp <- 141 / sqrt(69.5 * 290)
  r2_exp <- 141^2 / (69.5 * 290)
  b1_exp <- 141 / 69.5
  t_exp <- r_exp * sqrt(6 / (1 - r2_exp))
  p_exp <- 2 * stats::pt(-abs(t_exp), df = 6)
  z_exp <- 0.5 * log((1 + r_exp) / (1 - r_exp))
  ci_exp <- tanh(z_exp + c(-1, 1) * stats::qnorm(0.975) / sqrt(5))

  pe <- lc_val_cor(res, "Pearson Correlation")
  r2 <- lc_val_cor(res, "R-squared (Effect Size)")
  sl <- lc_val_cor(res, "Regression Slope")

  expect_equal(pe$value,    r_exp,     tolerance = 1e-8)
  expect_equal(pe$ci_lower, ci_exp[1], tolerance = 1e-8)
  expect_equal(pe$ci_upper, ci_exp[2], tolerance = 1e-8)
  expect_equal(pe$pvalue,   p_exp,     tolerance = 1e-8)
  expect_equal(r2$value,    r2_exp,    tolerance = 1e-8)
  expect_equal(sl$value,    b1_exp,    tolerance = 1e-8)
  expect_equal(sl$pvalue,   p_exp,     tolerance = 1e-8)
})

test_that("C14: Spearman rho and exact/asymptotic p-values match independent rank & permutation oracles", {
  # Oracle: closed-form midrank correlation & asymptotic t-test (tied) + 6! = 720 exact permutation p (untied)
  skip_if_not_installed("jmvcore")
  skip_if_not_installed("ggplot2")

  # Tied dataset
  d_tied <- data.frame(time = c(1, 2, 2, 4, 5, 6, 8, 10), val = c(2, 5, 3, 8, 10, 12, 15, 21))
  res_t <- suppressWarnings(ClinicoPath::linechart(data = d_tied, xvar = "time", yvar = "val", trendline = TRUE))
  sp_t <- lc_val_cor(res_t, "Spearman Correlation (Rank-based)")
  rho_exp <- sqrt(41.5 / 42)
  p_asymp <- 2 * stats::pt(-abs(rho_exp * sqrt(6 / (1 - rho_exp^2))), df = 6)
  expect_equal(sp_t$value,  rho_exp, tolerance = 1e-8)
  expect_equal(sp_t$pvalue, p_asymp, tolerance = 1e-8)
  expect_match(sp_t$interpretation, "asymptotic approximation because tied ranks", fixed = TRUE)

  # Untied dataset (n = 6, sum(d^2) = 6 -> rho = 29/35, exact 2-sided p = 42/720 = 7/120)
  d_untied <- data.frame(x = 1:6, y = c(2, 1, 4, 3, 6, 5))
  res_u <- suppressWarnings(ClinicoPath::linechart(data = d_untied, xvar = "x", yvar = "y", trendline = TRUE))
  sp_u <- lc_val_cor(res_u, "Spearman Correlation (Rank-based)")
  expect_equal(sp_u$value,  29 / 35, tolerance = 1e-8)
  expect_equal(sp_u$pvalue, 42 / 720, tolerance = 1e-6)
  expect_false(grepl("tied ranks", sp_u$interpretation, fixed = TRUE))
})

