test_that("C09-C14: Bundled ClinicoPath datasets and canonical cars match closed-form oracles", {
  # Oracle: closed-form Pearson/OLS on ClinicoPath::linechart_simple, linechart_grouped, and datasets::cars
  skip_if_not_installed("jmvcore")
  skip_if_not_installed("ggplot2")

  res_cars <- suppressWarnings(ClinicoPath::linechart(data = datasets::cars, xvar = "speed", yvar = "dist", trendline = TRUE))
  x <- datasets::cars$speed; y <- datasets::cars$dist
  r_cars <- sum((x - mean(x)) * (y - mean(y))) / sqrt(sum((x - mean(x))^2) * sum((y - mean(y))^2))
  expect_equal(lc_val_cor(res_cars, "Pearson Correlation")$value, r_cars, tolerance = 1e-8)
  expect_equal(lc_val_cor(res_cars, "R-squared (Effect Size)")$value, r_cars^2, tolerance = 1e-8)

  res_s <- suppressWarnings(ClinicoPath::linechart(
    data = ClinicoPath::linechart_simple, xvar = "time_point", yvar = "value", trendline = TRUE
  ))
  xs <- ClinicoPath::linechart_simple$time_point; ys <- ClinicoPath::linechart_simple$value
  b1_s <- sum((xs - mean(xs)) * (ys - mean(ys))) / sum((xs - mean(xs))^2)
  expect_equal(lc_val_cor(res_s, "Regression Slope")$value, b1_s, tolerance = 1e-8)

  lg <- ClinicoPath::linechart_grouped
  lg_cc <- lg[complete.cases(lg[, c("time_point", "lab_value", "treatment")]), ]
  res_g <- suppressWarnings(ClinicoPath::linechart(
    data = lg, xvar = "time_point", yvar = "lab_value", groupby = "treatment", trendline = TRUE
  ))
  expect_equal(as.numeric(lc_val_sum(res_g, "Number of Observations")), nrow(lg_cc))
})

test_that("C09-C14: Metamorphic invariants hold (permutation, negation, affine scaling, monotone X, jamovi values-attr)", {
  # Oracle: mathematical invariance & equivariance identities of Pearson, Spearman, and OLS
  skip_if_not_installed("jmvcore")
  skip_if_not_installed("ggplot2")

  set.seed(20260102)
  d <- data.frame(
    t = 1:20,
    y = 10 + 1.5 * (1:20) + rnorm(20, 0, 3),
    grp = factor(rep(c("Arm B", "Arm A"), each = 10), levels = c("Arm B", "Arm A"))
  )
  r0 <- suppressWarnings(ClinicoPath::linechart(data = d, xvar = "t", yvar = "y", trendline = TRUE))
  r_perm <- suppressWarnings(ClinicoPath::linechart(data = d[sample(nrow(d)), ], xvar = "t", yvar = "y", trendline = TRUE))
  expect_equal(lc_val_cor(r_perm, "Pearson Correlation")$value, lc_val_cor(r0, "Pearson Correlation")$value, tolerance = 1e-12)

  # Negation
  d_neg <- d; d_neg$y <- -d_neg$y
  r_neg <- suppressWarnings(ClinicoPath::linechart(data = d_neg, xvar = "t", yvar = "y", trendline = TRUE))
  expect_equal(lc_val_cor(r_neg, "Pearson Correlation")$value, -lc_val_cor(r0, "Pearson Correlation")$value, tolerance = 1e-12)
  expect_equal(lc_val_cor(r_neg, "Pearson Correlation")$ci_lower, -lc_val_cor(r0, "Pearson Correlation")$ci_upper, tolerance = 1e-12)
  expect_equal(lc_val_cor(r_neg, "Regression Slope")$value, -lc_val_cor(r0, "Regression Slope")$value, tolerance = 1e-12)

  # Affine X scaling
  d_scx <- d; d_scx$t <- 10 * d_scx$t + 5
  r_scx <- suppressWarnings(ClinicoPath::linechart(data = d_scx, xvar = "t", yvar = "y", trendline = TRUE))
  expect_equal(lc_val_cor(r_scx, "Regression Slope")$value, lc_val_cor(r0, "Regression Slope")$value / 10, tolerance = 1e-10)
  expect_equal(lc_val_cor(r_scx, "Pearson Correlation")$value, lc_val_cor(r0, "Pearson Correlation")$value, tolerance = 1e-10)

  # Monotone X transform preserves Spearman
  d_nlx <- d; d_nlx$t <- exp(d_nlx$t / 5)
  r_nlx <- suppressWarnings(ClinicoPath::linechart(data = d_nlx, xvar = "t", yvar = "y", trendline = TRUE))
  expect_equal(lc_val_cor(r_nlx, "Spearman Correlation (Rank-based)")$value,
               lc_val_cor(r0, "Spearman Correlation (Rank-based)")$value, tolerance = 1e-12)

  # jamovi values-attributed factor yvar unwraps values instead of level codes
  y_f <- factor(c(10L, 25L, 40L, 55L, 70L, 85L))
  attr(y_f, "values") <- as.integer(levels(y_f))
  r_jmv <- suppressWarnings(ClinicoPath::linechart(data = data.frame(x = 1:6, y = y_f), xvar = "x", yvar = "y", trendline = TRUE))
  expect_equal(lc_val_cor(r_jmv, "Regression Slope")$value, 15.0, tolerance = 1e-8)
})

test_that("C20, C24: Plot OLS 95% CI band matches closed-form formula and jamovi redraw succeeds with private$.data = NULL", {
  # Oracle: closed-form OLS confidence band yhat +/- t_{0.975, n-2} * sigma * sqrt(1/n + (x0 - xbar)^2 / Sxx)
  skip_if_not_installed("jmvcore")
  skip_if_not_installed("ggplot2")

  d <- data.frame(time = c(1, 2, 2, 4, 5, 6, 8, 10), val = c(2, 5, 3, 8, 10, 12, 15, 21))
  res <- suppressWarnings(ClinicoPath::linechart(data = d, xvar = "time", yvar = "val", confidence = TRUE, trendline = TRUE))
  tmp <- tempfile(fileext = ".png")
  on.exit(unlink(tmp), add = TRUE)
  suppressWarnings(suppressMessages(res$plot$saveAs(tmp)))
  expect_true(file.exists(tmp) && file.info(tmp)$size > 0)

  gb <- suppressWarnings(ggplot2::ggplot_build(ggplot2::last_plot()))
  sm <- gb$data[[1]]
  x <- d$time; y <- d$val; n <- length(x)
  sxx <- sum((x - mean(x))^2); b1 <- sum((x - mean(x)) * (y - mean(y))) / sxx; b0 <- mean(y) - b1 * mean(x)
  sigma <- sqrt(sum((y - (b0 + b1 * x))^2) / (n - 2))
  yhat <- b0 + b1 * sm$x
  se_fit <- sigma * sqrt(1 / n + (sm$x - mean(x))^2 / sxx)
  tcrit <- stats::qt(0.975, df = n - 2)
  expect_equal(sm$y,    yhat, tolerance = 1e-8)
  expect_equal(sm$ymin, yhat - tcrit * se_fit, tolerance = 1e-8)
  expect_equal(sm$ymax, yhat + tcrit * se_fit, tolerance = 1e-8)

  # jamovi redraw with private$.data cleared
  opt <- ClinicoPath:::linechartOptions$new(xvar = "time", yvar = "val", confidence = TRUE)
  a1 <- ClinicoPath:::linechartClass$new(options = opt, data = d)
  suppressWarnings(a1$run())
  a2 <- ClinicoPath:::linechartClass$new(options = opt, data = d)
  a2$init()
  a2$.__enclos_env__$private$.data <- NULL
  a2$results$plot$setState(a1$results$plot$state)
  tmp2 <- tempfile(fileext = ".png")
  on.exit(unlink(tmp2), add = TRUE)
  grDevices::png(tmp2, 400, 300)
  ok <- suppressWarnings(suppressMessages(a2$.__enclos_env__$private$.plot(a2$results$plot, ggplot2::theme_gray(), list())))
  grDevices::dev.off()
  expect_true(isTRUE(ok) && file.exists(tmp2) && file.info(tmp2)$size > 0)
})

lc_val_notices <- function(res) {
  notice_txt <- vapply(
    Filter(function(item) inherits(item, "Notice"), res$items),
    function(item) as.character(if (is.null(item$content)) "" else item$content),
    character(1)
  )
  paste(notice_txt, collapse = " ")
}

test_that("C23: Guard thresholds fire accurately at T-1, T, and T+1", {
  # Oracle: documented thresholds min_obs=3, trend_n<5, ci_n<10, many_groups>8, small_group<3
  skip_if_not_installed("jmvcore")
  skip_if_not_installed("ggplot2")

  set.seed(20260105)
  expect_error(
    ClinicoPath::linechart(data = data.frame(x = 1:2, y = c(1, 3)), xvar = "x", yvar = "y"),
    "At least 3 complete observations"
  )
  expect_false(grepl("At least 3 complete observations", lc_val_notices(ClinicoPath::linechart(data = data.frame(x = 1:3, y = c(1, 3, 2)), xvar = "x", yvar = "y")), fixed = TRUE))
  expect_true(grepl("Less than 5 data points", lc_val_notices(ClinicoPath::linechart(data = data.frame(x = 1:4, y = c(1, 3, 2, 5)), xvar = "x", yvar = "y", trendline = TRUE)), fixed = TRUE))
  expect_false(grepl("Less than 5 data points", lc_val_notices(ClinicoPath::linechart(data = data.frame(x = 1:5, y = c(1, 3, 2, 5, 4)), xvar = "x", yvar = "y", trendline = TRUE)), fixed = TRUE))
  expect_true(grepl("Small sample size (< 10", lc_val_notices(ClinicoPath::linechart(data = data.frame(x = 1:9, y = rnorm(9)), xvar = "x", yvar = "y", confidence = TRUE)), fixed = TRUE))
  expect_false(grepl("Small sample size (< 10", lc_val_notices(ClinicoPath::linechart(data = data.frame(x = 1:10, y = rnorm(10)), xvar = "x", yvar = "y", confidence = TRUE)), fixed = TRUE))
})

