test_that("C18 [VAL-linechart-04]: Linearity diagnostic controls false-positive rate under true linear model and catches cubic curves", {
  # Oracle: nested partial F-test at alpha = 0.05 has ~5% FP rate on linear truth and detects y = x^3
  skip_if_not_installed("jmvcore")
  skip_if_not_installed("ggplot2")
  set.seed(20260110)
