    y = c(10,11,12, 20,21,22, 12,13,14, 22,23,24, 14,15,16, 24,25,26),
    arm = factor(rep(rep(c("A", "B"), each = 3), 3))
  )
  res <- ClinicoPath::linechart(data = d, xvar = "visit", yvar = "y", groupby = "arm", trendline = TRUE)
  txt <- paste(res$correlation$asDF$interpretation, collapse = " ")
  expect_match(txt, "limitation|caution|pool|independent", ignore.case = TRUE)
})

test_that("C19, C20 [VAL-linechart-10]: Confidence band does not draw unrequested line, maps group fill, and avoids duplicate LOESS", {
  # Oracle: geom_smooth ribbon-only when trendline=FALSE, fill mapped to groupby, single LOESS layer when smooth=TRUE & confidence=TRUE
  skip_if_not_installed("jmvcore")
  skip_if_not_installed("ggplot2")
  d <- data.frame(t = rep(1:10, 2), y = c(1:10 + 1, 1:10 + 5), g = factor(rep(c("A", "B"), each = 10)))
  res <- ClinicoPath::linechart(data = d, xvar = "t", yvar = "y", groupby = "g", confidence = TRUE, smooth = FALSE, trendline = FALSE)
  tmp <- tempfile(fileext = ".png"); on.exit(unlink(tmp), add = TRUE)
  suppressWarnings(suppressMessages(res$plot$saveAs(tmp)))
  gb <- suppressWarnings(ggplot2::ggplot_build(ggplot2::last_plot()))
  expect_equal(length(unique(gb$data[[1]]$fill)), 2L)
  expect_true(all(is.na(gb$data[[1]]$colour)))

  res_lo <- ClinicoPath::linechart(data = d[1:10, ], xvar = "t", yvar = "y", confidence = TRUE, smooth = TRUE)
  tmp2 <- tempfile(fileext = ".png"); on.exit(unlink(tmp2), add = TRUE)
  suppressWarnings(suppressMessages(res_lo$plot$saveAs(tmp2)))
  p_lo <- ggplot2::last_plot()
  expect_equal(sum(vapply(p_lo$layers, function(l) inherits(l$geom, "GeomSmooth"), logical(1))), 1L)
})

test_that("C24 [VAL-linechart-11 / IR-LC-12]: Rejections propagate cleanly via reject() and constant X hides empty correlation", {
  # Oracle: fatal validation failures must propagate via jmvcore::reject() so jamovi
  # greys out prior results and displays its error banner; constant X hides 0-row correlation
  skip_if_not_installed("jmvcore")
  skip_if_not_installed("ggplot2")
  expect_error(
    ClinicoPath::linechart(data = data.frame(x = 1:2, y = c(1, 2)), xvar = "x", yvar = "y", trendline = TRUE),
    "At least 3 complete observations"
  )
  res_cx <- ClinicoPath::linechart(data = data.frame(x = rep(5, 10), y = 1:10), xvar = "x", yvar = "y", trendline = TRUE)
  expect_false(isTRUE(res_cx$correlation$visible) && nrow(res_cx$correlation$asDF) == 0L)

  opt <- ClinicoPath:::linechartOptions$new(xvar = "x", yvar = "y", trendline = TRUE)
  a <- ClinicoPath:::linechartClass$new(options = opt, data = data.frame(x = 1:8, y = c(2, 5, 3, 8, 10, 12, 15, 21)))
  suppressWarnings(a$run())
  expect_true(isTRUE(a$results$correlation$visible) && nrow(a$results$correlation$asDF) > 0L)
  a$.__enclos_env__$private$.data <- data.frame(x = c(1, 2), y = c(10, 20))
  expect_error(a$run(), "At least 3 complete observations")
})

test_that("C16 [VAL-linechart-13]: Copy-Ready Summary reports exact p, 95% CI, test name, N, and avoids 'p = 0.05' contradiction", {
  # Oracle: SAMPL/APA reporting standards; exact p to 3 decimals for p >= 0.001, no rounding p=0.0499 to 'p = 0.05' alongside 'significant'
  skip_if_not_installed("jmvcore")
  skip_if_not_installed("ggplot2")
  t_004 <- stats::qt(1 - 0.004 / 2, df = 28)
  r_004 <- t_004 / sqrt(t_004^2 + 28)
  cr <- lc_val_cor(ClinicoPath::linechart(data = lc_val_make_r(30, r_004), xvar = "x", yvar = "y", trendline = TRUE), "Copy-Ready Summary")$interpretation
  expect_match(cr, "p = 0.004", fixed = TRUE)
  expect_match(cr, "95% CI", fixed = TRUE)
  expect_match(cr, "Pearson", fixed = TRUE)
  expect_match(cr, "N = 30", fixed = TRUE)

  t_0499 <- stats::qt(1 - 0.0499 / 2, df = 28)
  r_0499 <- t_0499 / sqrt(t_0499^2 + 28)
  cr2 <- lc_val_cor(ClinicoPath::linechart(data = lc_val_make_r(30, r_0499), xvar = "x", yvar = "y", trendline = TRUE), "Copy-Ready Summary")$interpretation
  expect_match(cr2, "p = 0.0499", fixed = TRUE)
})

