test_that("Security: .sourcifyOption escapes quotes/backslashes/newlines and drops undeclared/list options", {
  skip_if_not_installed("jmvcore")
  skip_if_not_installed("ggplot2")

  d <- data.frame(t = 1:6, y = c(10, 12, 15, 17, 21, 24))
  payloads <- c(
    'My Plot", xlabel = {stop("CANARY"); "X"}, ylabel = "Y',
    'trailing\\',
    "line1\nline2"
  )

  # Quote-breaking / backslash / newline payloads on OptionString (title) and non-String (theme)
  for (opt_name in c("title", "theme")) {
    for (p in payloads) {
      opt <- ClinicoPath:::linechartOptions$new(xvar = "t", yvar = "y")
      an <- ClinicoPath:::linechartClass$new(options = opt, data = d)
      o <- an$options$option(opt_name)
      o$value <- p
      ex <- parse(text = an$asSource())[[1]]
      args <- as.list(ex)[-1]
      expect_identical(args[[opt_name]], p)
      expect_true(all(names(args) %in% c("data", "xvar", "yvar", opt_name)))
      expect_false(any(vapply(args, is.call, logical(1))))
    }
  }

  # Undeclared option name must be dropped completely
  opt_u <- ClinicoPath:::linechartOptions$new(xvar = "t", yvar = "y")
  an_u <- ClinicoPath:::linechartClass$new(options = opt_u, data = d)
  an_u$options$.addOption(jmvcore:::Option$new('title = "A", xlabel = {stop("CANARY"); "X"}, ylabel', "Y"))
  ex_u <- parse(text = an_u$asSource())[[1]]
  expect_true(all(names(as.list(ex_u))[-1] %in% c("data", "xvar", "yvar")))

  # List value must be dropped completely
  opt_l <- ClinicoPath:::linechartOptions$new(xvar = "t", yvar = "y")
  an_l <- ClinicoPath:::linechartClass$new(options = opt_l, data = d)
  ol <- an_l$options$option("title")
  ol$value <- list('a" = {stop("CANARY"); 1}, b' = 1)
  ex_l <- parse(text = an_l$asSource())[[1]]
  expect_false("title" %in% names(as.list(ex_l))[-1])
})

test_that("Security: run(noThrow = TRUE) backstops clamp invalid dimensions and non-logical flags", {
  skip_if_not_installed("jmvcore")
  skip_if_not_installed("ggplot2")

  d <- data.frame(t = 1:6, y = c(10, 12, 15, 17, 21, 24))
  opt <- ClinicoPath:::linechartOptions$new(xvar = "t", yvar = "y")
  an <- ClinicoPath:::linechartClass$new(options = opt, data = d)
  ow <- an$options$option("width"); ow$value <- 99999L
  oh <- an$options$option("height"); oh$value <- -10L
  ot <- an$options$option("trendline"); ot$value <- "not_a_bool"
  expect_no_error({
    an$.__enclos_env__$private$.init()
    an$.__enclos_env__$private$.run()
  })
  expect_equal(an$results$plot$width, 800L)
  expect_equal(an$results$plot$height, 600L)
})
